const hookHost = new HookHost();

export function useState(initialState) {
	return hookHost.useState(initialState);
}

export function useReducer(reducer, initialState, init) {
	return hookHost.useReducer(reducer, initialState, init);
}

export function useEffect(callback, args) {
	return hookHost.useEffect(callback, args);
}

export function useLayoutEffect(callback, args) {
	return hookHost.useLayoutEffect(callback, args);
}

export function useRef(initialValue) {
	return hookHost.useRef(initialValue);
}

export function useImperativeHandle(ref, createHandle, args) {
	return hookHost.useImperativeHandle(ref, createHandle, args);
}

export function useMemo(factory, args) {
	return hookHost.useMemo(factory, args);
}

export function useCallback(callback, args) {
	return hookHost.useCallback(callback, args);
}

export function useContext(context) {
	return hookHost.useContext(context);
}

export function useDebugValue(value, formatter) {
	return hookHost.useDebugValue(value, formatter);
}

export function useErrorBoundary(cb) {
	return hookHost.useErrorBoundary(cb);
}

