input.newString:
invokeCleanup(hook) {
	const comp = this._currentComponent;
	this.observeHookSurface(3, { kind: 3, list: hook ? [hook] : null });
	try {
		if (typeof hook._cleanup == 'function') {
			const cleanup = hook._cleanup;
			hook._cleanup = undefined;
			cleanup();
		}
	} finally {
		this._currentComponent = comp;
	}
}

